custom_qss:
/* ============================================================
   TERMINAL — shell / ASCII look. Heavy monospace everywhere, >>
   prompt markers on interactive elements, glyph stand-ins, bright
   green on near-black. Reads like a TTY, not a GUI.
   ============================================================ */

* { font-family: "Cascadia Code", Consolas, "DejaVu Sans Mono", monospace; color: #8dffb0; }
QAbstractScrollArea, QFrame, QStackedWidget, QScrollArea, QTabWidget, QWidget { background: transparent; border: none; }

QMainWindow { background: #020803 !important; border: none; }
QDialog { background: #04140a !important; border: 1px solid #125c2c; }

QMenuBar { background: #031007 !important; border: none; border-bottom: 1px solid #0c3a1c; }
QMenuBar::item { padding: 5px 12px; background: transparent !important; color: #5fd98a; }
QMenuBar::item::text { /* prefix handled by content */ }
QMenuBar::item:selected { background: #0a2a14 !important; color: #5cff8f; }
QMenuBar::item:disabled { color: #1f5c36; }

QMenu { background: #04140a !important; border: 1px solid #125c2c; padding: 5px; font-size: 12px;}
QMenu::item { padding: 6px 24px 6px 12px; background: transparent !important; color: #8dffb0; }
QMenu::item:selected { background: #0a2a14 !important; color: #5cff8f; }
QMenu::item:disabled { color: #1f5c36; }
QMenu::separator { height: 1px; background: #0c3a1c; margin: 5px 10px; }

QToolBar { background: #031007 !important; border: none; border-bottom: 1px solid #0c3a1c; spacing: 2px; padding: 4px; }
QToolBar::separator { background: #0c3a1c; width: 1px; margin: 6px 4px; }
QToolBar QToolButton, QToolButton { background: transparent !important; padding: 6px 11px; border: 1px solid transparent; color: #5fd98a; font-size: 12px;}
QToolBar QToolButton:hover, QToolButton:hover { background: #0a2a14 !important; border: 1px solid #125c2c; color: #5cff8f; }
QToolBar QToolButton:checked, QToolBar QToolButton:pressed, QToolButton:checked, QToolButton:pressed { background: #5cff8f !important; color: #020803; }

QPushButton { background: #04140a !important; border: 1px solid #125c2c; border-radius: 2px; padding: 7px 20px; color: #8dffb0; font-weight: 600; font-size: 12px;}
QPushButton:hover { background: #0a2a14 !important; border: 1px solid #5cff8f; color: #5cff8f; }
QPushButton:pressed { background: #5cff8f !important; color: #020803; }
QPushButton:checked { background: #0a2a14 !important; border: 1px solid #5cff8f; color: #5cff8f; }
QPushButton:default { border: 1px solid #5cff8f; }
QPushButton:disabled { background: #031007 !important; color: #1f5c36; }

QLineEdit, QSpinBox, QDoubleSpinBox, QTextEdit, QPlainTextEdit { background: #010602 !important; border: 1px solid #0c3a1c; border-radius: 2px; padding: 6px 11px; color: #5cff8f; selection-background-color: #5cff8f; selection-color: #020803; font-size: 12px;}
QLineEdit:disabled, QSpinBox:disabled, QDoubleSpinBox:disabled, QTextEdit:disabled, QPlainTextEdit:disabled { color: #1f5c36; }

QDockWidget { background: #04140a !important; border: 1px solid #0c3a1c; border-radius: 2px; }
QDockWidget::title { background: #031007 !important; border: none; border-bottom: 1px solid #0c3a1c; border-left: 3px solid #5cff8f; padding: 7px 11px; color: #5cff8f; font-weight: 700; }
QDockWidget::close-button, QDockWidget::float-button { background: transparent !important; border: 1px solid transparent; border-radius: 2px; padding: 3px; icon-size: 16px; }
QDockWidget::close-button:hover, QDockWidget::float-button:hover { background: #0a2a14 !important; }

QGroupBox { background: transparent !important; border: 1px solid #0c3a1c; border-radius: 2px; margin-top: 13px; padding-top: 11px; }
QGroupBox::title { subcontrol-origin: margin; subcontrol-position: top left; padding: 0 9px; color: #5cff8f; font-weight: 700; background: #020803; }

QSpinBox::up-button, QSpinBox::down-button, QDoubleSpinBox::up-button, QDoubleSpinBox::down-button { background: transparent !important; border: none; width: 16px; }
QComboBox { background: #010602 !important; border: 1px solid #0c3a1c; border-radius: 3px; padding: 6px 10px; color: #8dffb0; font-size: 12px;}
QComboBox:hover { border: 1px solid #125c2c; }
QComboBox:focus { border: 1px solid #5cff8f; }
QComboBox::drop-down { border: none; background: transparent !important; width: 18px; }
QComboBox QAbstractItemView { background: #04140a !important; border: 1px solid #125c2c; padding: 5px; selection-background-color: #5cff8f; selection-color: #020803; font-size: 12px;}
QCheckBox, QRadioButton { color: #8dffb0; background: transparent !important; padding: 3px; }
QCheckBox::indicator, QRadioButton::indicator { width: 15px; height: 15px; border-radius: 2px; background: #010602 !important; border: 1px solid #125c2c; }
QRadioButton::indicator { border-radius: 8px; }
QCheckBox::indicator:hover, QRadioButton::indicator:hover { border: 1px solid #5cff8f; }
QCheckBox::indicator:checked, QRadioButton::indicator:checked { background: #5cff8f !important; border: 1px solid #5cff8f; }
QTabBar::tab { background: transparent !important; color: #3a9e5c; padding: 8px 16px; border: none; border-bottom: 2px solid transparent; }
QTabBar::tab:hover { color: #8dffb0; }
QTabBar::tab:selected { color: #5cff8f; border-bottom: 2px solid #5cff8f; }
QTabWidget::pane { border: none; }
QAbstractItemView { background: #010602 !important; border: 1px solid #0c3a1c; border-radius: 3px; outline: none; alternate-background-color: #031007; selection-background-color: #5cff8f; selection-color: #020803; }
QAbstractItemView::item { padding: 5px 10px; border: none; color: #8dffb0; }
QAbstractItemView::item:hover { background: #0a2a14 !important; color: #5cff8f; }
QAbstractItemView::item:selected { background: #5cff8f !important; color: #020803 !important; }
QTreeView::branch { background: transparent !important; }
QHeaderView::section { background: #031007 !important; border: none; border-bottom: 1px solid #125c2c; padding: 6px 10px; color: #5fd98a; font-weight: 700; }
QScrollBar:vertical { background: #010602; width: 10px; margin: 0; border: none; }
QScrollBar::handle:vertical { background: #125c2c; border-radius: 2px; min-height: 30px; }
QScrollBar::handle:vertical:hover { background: #5cff8f; }
QScrollBar::add-line:vertical, QScrollBar::sub-line:vertical { height: 0; border: none; background: none; }
QScrollBar::add-page:vertical, QScrollBar::sub-page:vertical { background: none; }
QScrollBar:horizontal { background: #010602; height: 10px; margin: 0; border: none; }
QScrollBar::handle:horizontal { background: #125c2c; border-radius: 2px; min-width: 30px; }
QScrollBar::handle:horizontal:hover { background: #5cff8f; }
QScrollBar::add-line:horizontal, QScrollBar::sub-line:horizontal { width: 0; border: none; background: none; }
QScrollBar::add-page:horizontal, QScrollBar::sub-page:horizontal { background: none; }
QScrollBar::corner { background: none; }
QSlider::groove:horizontal { background: #010602; border: 1px solid #0c3a1c; height: 6px; border-radius: 3px; }
QSlider::sub-page:horizontal { background: #5cff8f; border-radius: 3px; }
QSlider::add-page:horizontal { background: #010602; border-radius: 3px; }
QSlider::handle:horizontal { background: #5cff8f; width: 13px; height: 15px; margin: -5px 0; border: 2px solid #020803; border-radius: 8px; }
QSlider::handle:horizontal:hover { background: #a8ffc4; }
QSlider::groove:vertical { background: #010602; border: 1px solid #0c3a1c; width: 6px; border-radius: 3px; }
QSlider::sub-page:vertical { background: #5cff8f; border-radius: 3px; }
QSlider::handle:vertical { background: #5cff8f; width: 15px; height: 13px; margin: 0 -5px; border: 2px solid #020803; border-radius: 8px; }
QProgressBar { background: #010602; border: 1px solid #0c3a1c; border-radius: 3px; text-align: center; color: #5fd98a; font-size: 11px; min-height: 15px; }
QProgressBar::chunk { background: #5cff8f; border-radius: 2px; }
QStatusBar { background: #031007 !important; color: #3a9e5c; font-size: 11px; }
QStatusBar::item { border: none; }
QToolTip { background: #04140a !important; border: 1px solid #5cff8f; border-radius: 3px; padding: 6px 10px; color: #8dffb0; }
QSplitter::handle { background: #0c3a1c; }
QSplitter::handle:hover { background: #5cff8f; }
QListView, QListWidget, QTreeWidget, QTableWidget { background: #010602 !important; border: 1px solid #0c3a1c; border-radius: 3px; outline: none; }
